import re

class WalletAddressError(Exception):
    """Custom exception for invalid wallet addresses."""
    pass

def is_valid_solana_address(address: str) -> bool:
    """
    Verify if the provided Solana wallet address is valid.

    Args:
        address (str): The wallet address to validate.

    Returns:
        bool: True if the address is valid, False otherwise.

    Raises:
        WalletAddressError: If the address format is invalid.
    """
    # Solana wallet addresses are base58 encoded and typically 44 characters long
    base58_pattern = r'^[1-9A-HJ-NP-Za-km-z]{32,44}$'
    
    if not isinstance(address, str):
        raise WalletAddressError("Wallet address must be a string.")
    
    if not re.match(base58_pattern, address):
        raise WalletAddressError("Invalid Solana wallet address format.")
    
    return True

